import { NextResponse, type NextRequest } from "next/server";
import { getSessionCookie } from "better-auth/cookies";

// Optimistic check only (cookie presence). Real validation happens in
// getCurrentUser() on the page itself.
export function proxy(request: NextRequest) {
  if (!getSessionCookie(request)) {
    const url = new URL("/sign-in", request.url);
    url.searchParams.set("next", request.nextUrl.pathname);
    return NextResponse.redirect(url);
  }
  return NextResponse.next();
}

export const config = {
  matcher: ["/dashboard/:path*"],
};
EOF
cat > src/lib/users.ts <<'EOF'
import { headers } from "next/headers";
import { auth } from "./auth";
import { db } from "./db";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = { id: string; email: string; name: string; createdAt: string };

function toUser(row: UserRow): User {
  return { ...row, createdAt: new Date(row.createdAt).toISOString().slice(0, 10) };
}

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare('SELECT id, email, name, createdAt FROM "user" ORDER BY createdAt')
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare('SELECT id, email, name, createdAt FROM "user" WHERE id = ?')
    .get(id) as UserRow | undefined;
  return row && toUser(row);
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? getUser(session.user.id) : undefined;
}
EOF
cat > src/components/auth-form.tsx <<'EOF'
"use client";

import { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { authClient } from "@/lib/auth-client";

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const params = useSearchParams();
  const rawNext = params.get("next") ?? "/dashboard";
  // only allow same-site relative paths
  const next = rawNext.startsWith("/") && !rawNext.startsWith("//") ? rawNext : "/dashboard";
  const [error, setError] = useState<string>();
  const [pending, setPending] = useState(false);

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(undefined);
    setPending(true);
    const f = new FormData(e.currentTarget);
    const email = String(f.get("email"));
    const password = String(f.get("password"));
    const { error } =
      mode === "sign-up"
        ? await authClient.signUp.email({ email, password, name: String(f.get("name")) })
        : await authClient.signIn.email({ email, password });
    setPending(false);
    if (error) return setError(error.message ?? "Something went wrong");
    router.push(next);
    router.refresh();
  }

  const input = "w-full rounded border border-black/20 bg-transparent px-3 py-2 text-sm dark:border-white/25";
  const button = "w-full rounded bg-foreground px-3 py-2 text-sm text-background disabled:opacity-50";

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{mode === "sign-in" ? "Sign in" : "Create account"}</h1>
      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {mode === "sign-up" && (
          <input name="name" placeholder="Name" required autoComplete="name" className={input} />
        )}
        <input name="email" type="email" placeholder="Email" required autoComplete="email" className={input} />
        <input
          name="password"
          type="password"
          placeholder="Password"
          required
          minLength={8}
          autoComplete={mode === "sign-in" ? "current-password" : "new-password"}
          className={input}
        />
        {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
        <button type="submit" disabled={pending} className={button}>
          {mode === "sign-in" ? "Sign in" : "Sign up"}
        </button>
      </form>
      <button
        type="button"
        onClick={() => authClient.signIn.social({ provider: "google", callbackURL: next })}
        className={`${button} mt-3 !bg-transparent !text-foreground border border-black/20 dark:border-white/25`}
      >
        Continue with Google
      </button>
      <p className="mt-6 text-sm opacity-70">
        {mode === "sign-in" ? (
          <>No account? <Link href="/sign-up" className="underline">Sign up</Link></>
        ) : (
          <>Already registered? <Link href="/sign-in" className="underline">Sign in</Link></>
        )}
      </p>
    </main>
  );
}
EOF
